-- Deities and Demigods: Asgardian pantheon divine stat blocks, batch D.
-- Source: Deities and Demigods (2002), Chapter 6, pp. 186-192.
-- Printed 3.0 statistics remain source-of-truth; official 3.5 conversion deltas are recorded separately.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Sun disk' WHERE source_id='dd-3.0' AND slug='odur' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Upraised sword' WHERE source_id='dd-3.0' AND slug='sif' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Mountain Peak' WHERE source_id='dd-3.0' AND slug='skadi' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Flaming sword' WHERE source_id='dd-3.0' AND slug='surtur' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-odur','Odur Divine Stat Block','186-187',
 'Odur is the divine-rank-4 Asgardian demigod of light, the sun, travel, and the day chariot.',
 '{"deitySlug":"odur","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"demigod","divineRank":4,"titles":["God of the Sun"],"symbol":"Sun disk","homePlane":"Asgard","alignment":"CG","classes":[{"class":"Fighter","level":20},{"class":"Sorcerer","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+320 outsider + 20d10+320 fighter + 20d4+320 sorcerer","hitPoints":1400,"initiative":13,"speed":{"land":60},"armorClass":{"total":55,"dexterity":9,"divine":4,"natural":17,"printedArmorFromShield":7,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"bastardSword":"+58/+53/+48/+43 melee, +5 brilliant energy bastard sword","bastardSwordDamage":"1d10+15/17-20","spellTouch":{"melee":52,"ranged":53}},"saves":{"fort":52,"ref":47,"will":45},"abilities":{"str":27,"dex":29,"con":42,"int":25,"wis":25,"cha":26},"specialQualities":{"printedDamageReduction":"39/+4","printedColdResistance":24,"sourceAnomaly":"The printed block lists cold resistance 24 even though divine immunities in the same block include cold; preserve both source statements.","spellResistance":36,"divineAura":{"radiusFeet":40,"dc":22},"familiar":"hawks","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Automatic Metamagic (quicken sorcerer spells)","Divine Radiance","Wave of Chaos"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"fireTurningUsesPerDay":11,"greaterTurningUsesPerDay":4},"spellLikeAbilities":{"casterLevel":14,"chaosCasterLevel":15,"saveDc":"22 + spell level"},"spellcasting":{"sorcererSpellsKnownPerDay":"6/8/8/8/8/7/7/7/7/6","sorcererBaseDc":"18 + spell level","arcaneSpellFailurePercent":15},"possessions":{"shield":"+5 arrow deflection reflecting large steel shield"},"portfolioSense":"Beginning of overland journeys greater than 30 miles involving at least 1,000 people, any overland journey over 1,000 miles regardless of group size, and forging any metal item worth more than 1,000 gp.","automaticActions":{"skills":["Craft (metalworking)","Handle Animal","Intuit Direction"],"freeActionDcMaximum":15,"maximumPerRound":2},"createMagicItems":{"scope":"items related to determining directions or controlling animals and teams of animals","maximumMarketPriceGp":4500},"avatarStatus":"Odur is rank 4 and does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"15/epic","fireResistance":9,"additionalOutsiderSkillPoints":true,"fighter":"No class-feature change in the official revision.","sorcerer":"No class-feature change in the official revision.","fireDomain":"Use revised Fire-domain spell names and resist energy where applicable.","defunctSkills":["Intuit Direction migrated","Scry ranks reassigned"]}}'),

('dd-statblock-sif','Sif Divine Stat Block','187-189',
 'Sif is the divine-rank-10 lesser Asgardian deity of war, dueling, excellence, and martial skill.',
 '{"deitySlug":"sif","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"lesser","divineRank":10,"titles":["Goddess of Excellence and Skill in Battle"],"symbol":"Upraised sword","homePlane":"Asgard","alignment":"CG","classes":[{"class":"Barbarian","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d12+160 barbarian + 20d10+160 fighter","hitPoints":1080,"initiative":"+20, always first","speed":{"land":70},"armorClass":{"total":84,"dexterity":16,"divine":10,"natural":23,"armorMithralShirt":9,"printedArmorMithralShield":7,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longsword":"+76/+76/+71/+66/+61 melee, +5 keen speed longsword","longswordDamage":"1d8+29/15-20"},"saves":{"fort":50,"ref":60,"will":52},"abilities":{"str":31,"dex":43,"con":26,"int":26,"wis":26,"cha":28},"specialQualities":{"printedDamageReduction":"45/+4 (4/-)","printedFireResistance":30,"spellResistance":42,"divineAura":{"radiusFeet":1000,"dc":29},"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Battlesense","Banestrike (evil outsiders)","Divine Armor Mastery","Divine Battle Mastery","Divine Celerity","Divine Dodge","Divine Inspiration (courage)","Divine Rage","Divine Weapon Focus (longsword)","Divine Weapon Specialization (longsword)","Longsword Finesse","Supreme Initiative"],"domainPowers":{"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":20,"chaosGoodCasterLevel":21,"saveDc":"29 + spell level"},"divineRage":{"usesPerDay":10,"duration":"1 hour or until ended","printedArmorClass":79,"printedHitPoints":1380,"printedAttack":"+81/+76/+71/+66 melee","printedDamage":"1d8+30/15-20","printedFireResistance":40,"printedSpellResistance":52,"printedFort":55,"printedWill":57,"printedStr":41,"printedCon":36},"uniqueAbilities":{"longswordFinesse":"May apply Dexterity bonus to attacks made with any longsword she can wield in one hand."},"possessions":{"armor":"+5 glamered heavy fortification mithral shirt","shield":"+5 arrow deflection reflecting large mithral shield","weapon":"+5 keen speed longsword"},"portfolioSense":"Battles involving at least 500 people and any battle in which a woman commands at least one side, regardless of size.","automaticActions":{"skills":["Bluff","Handle Animal","Intimidate","Ride (horse)","Tumble"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"any magic armor or weapon","maximumMarketPriceGp":30000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"20/epic","fireResistance":15,"additionalOutsiderSkillPoints":true,"barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRageNote":"Divine Rage replaces ordinary mighty rage for Sif.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"fighter":"No class-feature change in the official revision.","battlesense":"Replaces uncanny dodge and improved uncanny dodge.","divineCelerity":"Uses revised haste.","divineRage":"Instead of an extra partial action each round, revised Divine Rage grants one extra attack at full attack bonus whenever Sif uses the full attack action.","divineInspiration":"Use revised Divine Inspiration effects where applicable.","defunctSkills":["Intuit Direction migrated","Wilderness Lore -> Survival"],"defunctFeat":"Improved Sunder is replaced by the revised Improved Sunder feat; select a replacement feat if both printed Sunder/Improved Sunder would duplicate under 3.5."}}'),

('dd-statblock-skadi','Skadi Divine Stat Block','189-190',
 'Skadi is the divine-rank-6 lesser Asgardian deity of earth, mountains, winter wilderness, and mountain survival.',
 '{"deitySlug":"skadi","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"lesser","divineRank":6,"titles":["Goddess of Mountains","Snowshoe Goddess"],"symbol":"Mountain Peak","homePlane":"Asgard","alignment":"N","classes":[{"class":"Druid","level":20},{"class":"Ranger","level":20}],"creature":{"type":"Outsider","sourceSubtypes":["Cold"],"size":"Large","hitDice":"20d8+200 outsider + 20d8+200 druid + 20d10+200 ranger","hitPoints":1120,"initiative":8,"speed":{"land":80,"burrow":80},"armorClass":{"total":50,"size":-1,"dexterity":8,"divine":6,"natural":19,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"greataxe":"+68/+63/+58/+53 melee, Huge +5 bane icy burst thundering greataxe","greataxeVsFavoredEnemy":"+70/+65/+60/+55 melee","greataxeDamage":"2d8+29/19-20/x3","greataxeDamageVsFavoredEnemy":"2d6 plus 2d8+29/19-20/x3","spellTouch":{"melee":62,"ranged":54}},"saves":{"fort":48,"ref":48,"will":46},"abilities":{"str":42,"dex":27,"con":30,"int":25,"wis":26,"cha":26},"specialQualities":{"printedDamageReduction":"41/+4","printedFireResistance":26,"spellResistance":38,"divineAura":{"radiusFeet":600,"dc":24},"coldSubtypePrinted":"Immune to cold; double fire damage unless a half-damage save is allowed, then half on success and double on failure; fire resistance still applies.","tremorsense":true,"natureSense":true,"animalCompanion":"awakened dire bear","woodlandStride":true,"tracklessStep":true,"resistNaturesLure":true,"printedWildShape":"Tiny through Huge or dire animal 6/day; elemental 3/day","thousandFaces":true,"venomImmunity":true,"timelessBody":true,"printedFavoredEnemies":{"dragons":5,"undead":4,"magicalBeasts":3,"aberrations":2,"vermin":1},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Automatic Metamagic (quicken druid spells)","Battlesense","Divine Druid","Divine Earth Mastery","Divine Ranger","Shift Form"],"domainPowers":{"destructionSmiteUsesPerDay":6,"destructionSmiteAttackBonus":4,"destructionSmiteDamageBonus":6,"earthTurningPrintedUsesPerDay":11,"strengthFeatUsesPerDay":6,"strengthFeatBonus":6},"spellLikeAbilities":{"casterLevel":16,"saveDc":"24 + spell level"},"spellcasting":{"druidSpellsPerDay":"6/7/7/7/7/6/5/5/5/4","druidBaseDc":"18 + spell level","rangerSpellsPerDay":"5/5/5/5","rangerBaseDc":"18 + spell level"},"portfolioSense":"Natural events involving earth or mountains, such as mudslides, avalanches, or earthquakes, involving at least 500 people.","automaticActions":{"skills":["Animal Empathy","Climb","Intuit Direction","Jump","Wilderness Lore"],"freeActionDcMaximum":20,"maximumPerRound":5},"createMagicItems":{"scope":"items related to wilderness travel, wilderness survival, or mountain climbing","maximumMarketPriceGp":30000},"companions":["Awakened dire bear animal companion"],"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":[],"damageReduction":"20/epic","fireResistance":11,"additionalOutsiderSkillPoints":true,"spaceReach":"Large deity uses 10-ft. space and 10-ft. reach under revised size rules; printed 5x5/10 remains preserved above.","coldSubtype":"Use the revised Monster Manual cold-subtype and vulnerability rules rather than silently retaining the 3.0 double-damage text.","druid":{"spontaneousSummonNaturesAlly":true,"natureSenseBonus":{"Knowledge (nature)":2,"Survival":2},"wildEmpathy":true,"wildShape":"May become a plant creature and a Huge elemental under revised druid rules; also apply revised animal-companion rules."},"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1080,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"divineDruid":"Use revised Divine Druid form access, including animal, magical beast, or plant forms from Fine to Colossal where the salient ability applies.","divineRanger":"Apply Divine Ranger bane and tracking benefits to the revised favored-enemy framework.","battlesense":"Replaces uncanny dodge and improved uncanny dodge.","destructionDomain":"circle of doom is renamed mass inflict light wounds.","strengthDomain":"Replace endure elements with enlarge person.","defunctSkills":["Animal Empathy -> wild empathy","Intuit Direction migrated","Wilderness Lore -> Survival"]}}'),

('dd-statblock-surtur','Surtur Divine Stat Block','190-192',
 'Surtur is the divine-rank-14 intermediate Asgardian lord of the fire giants and deity of fire and war.',
 '{"deitySlug":"surtur","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":14,"titles":["Lord of the Fire Giants"],"symbol":"Flaming sword","homePlane":"Midgard (Muspelheim)","alignment":"LE","classes":[{"class":"Ranger","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","sourceSubtypes":["Evil","Fire","Lawful"],"size":"Gargantuan","hitDice":"20d8+200 outsider + 20d10+200 ranger + 20d10+200 fighter","hitPoints":1160,"initiative":12,"speed":{"land":120},"armorClass":{"total":63,"size":-4,"dexterity":8,"divine":14,"natural":27,"deflection":8},"face":"20 ft. by 20 ft.","reachFeet":20},"attacks":{"longsword":"+77/+72/+67/+62 melee, Gargantuan +5 brilliant energy flaming burst longsword","longswordDamage":"4d6+34/17-20","spellTouch":{"melee":71,"ranged":62}},"saves":{"fort":56,"ref":56,"will":57},"abilities":{"str":44,"dex":27,"con":31,"int":27,"wis":28,"cha":27},"specialQualities":{"printedDamageReduction":"49/+4","fastHealing":34,"spellResistance":46,"divineAura":{"radiusFeet":1400,"dc":32},"fireSubtype":"Immune to fire damage.","printedFavoredEnemies":{"Asgardian deities":5,"fey":4,"humans":3,"beasts":2,"animals":1},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Banestrike (good outsiders)","Call Creatures (fire elementals)","Divine Battle Mastery","Divine Fast Healing","Divine Fire Mastery","Divine Storm","Energy Burst (fire)","Energy Storm (fire)","Extra Domain (Strength)","Extra Domain (War)","Extra Energy Immunity (cold)","Indomitable Strength","Irresistible Blows","Shapechange","Sunder and Disjoin"],"domainPowers":{"evilSpellsCasterLevelBonus":1,"fireTurningUsesPerDay":14,"lawSpellsCasterLevelBonus":1,"strengthFeatUsesPerDay":14,"strengthFeatBonus":14},"spellLikeAbilities":{"casterLevel":24,"evilLawCasterLevel":25,"saveDc":"32 + spell level"},"spellcasting":{"rangerSpellsPerDay":"6/5/5/5","rangerBaseDc":"19 + spell level"},"portfolioSense":"Events involving giants or fires more than 10 feet across, regardless of number of people, in the present and fourteen weeks into the past.","automaticActions":{"skills":["Craft (metalworking)","Disguise","Profession (metalworker)"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"magic weapons or armor, wondrous items related to metalworking, and items that produce or use fire","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["evil","lawful"],"elementalSubtypes":["fire"],"damageReduction":"25/epic","fireImmunityFromSubtype":true,"coldImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1120,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; preserve the unusual printed Asgardian-deities/fey/humans/beasts/animals list as source data without inventing a new distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"fighter":"No class-feature change in the official revision.","irresistibleBlows":"Chosen-weapon attacks count as adamantine for overcoming DR and hardness.","fireDomain":"Use revised Fire-domain spell names and resist energy where applicable.","strengthDomain":"Replace endure elements with enlarge person.","defunctSkills":["Wilderness Lore -> Survival"],"defunctFeat":"Improved Sunder is replaced by the revised Improved Sunder feat; select a replacement feat if the printed feat list would duplicate under 3.5."}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-asgardian-pantheon',NULL,
  '["deities-and-demigods","asgardian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);